import sys; sys.stdout.reconfigure(encoding='utf-8')
import re
from docx import Document
from docx.oxml.ns import qn

MAIN = r'e:\DeskTop\knitting_pattern_generator\docs\论文to_cii.docx'
m = Document(MAIN)
ps = m.paragraphs

def rewrite(pre, new):
    p = next(p for p in ps if p.text.startswith(pre))
    assert not p._p.findall('.//' + qn('m:oMath')), ('oMath', pre)
    rr = p.runs; rr[0].text = new
    for r in rr[1:]: r._element.getparent().remove(r._element)
    return p

# ---------- 1) 恢复第一章（引言） ----------
REST = {}
REST['横机针织是柔性制造与个性化定制的核心技术'] = '横机针织作为柔性制造与个性化定制的核心技术，其生产效能高度依赖于设计意图向机台指令的精准转化。在工业实践中，动作色码图（action color map）是横机针织主流的花型表示与机台输入形式：打版师需在 Stoll M1 Plus、Shima Seiki SDS-ONE APEX 等工业级计算机辅助设计（CAD）系统中逐格指定每个针位的动作类别 [1, 2]。这类以针位与编织行为坐标、用图标或色块逐格标注动作的表格化表示，亦是针织机编程研究长期采用的主流范式 [3, 4]，但其自动化生成仍是当前产业现实紧缺的需求。在传统工业范式下，这一转化过程主要由专业打版师手动完成，然而随着智能制造对快速迭代的需求日益增长，这种依赖人工经验的模式已成为生产瓶颈。设计者通常以非结构化的自然语言描述纹理与空间布局，而电脑横机则要求在离散网格上精确定义针迹级动作。这种跨模态、跨层级的转化过程存在显著的表示断层（Representation Gap）：高层语义的模糊性与底层动作空间的严格约束性之间缺乏有效的映射机制，导致从创意到产品的转化周期漫长且不可控。'
REST['生成式 AI 已在纺织视觉设计领域'] = '尽管生成式人工智能在纺织视觉设计领域（如 ColorwAI [5]、FabricDiffusion [6]，相关综述见 [7]）取得了显著进展，但将其应用于横机动作色码图（Action Color Map）生成时，仍面临三个根本性的科学挑战。'
REST['首先是语义解析与拓扑映射的失稳'] = '首先是语义解析与拓扑映射的失稳。 自然语言描述（如“波浪吊目包裹圆形”）缺乏显式的几何边界与拓扑层级。虽然 LLM4CAD [8] 等研究尝试将自然语言转化为参数化模型，语义解析 [9]、结构化输出约束 [10] 与增量解析约束解码 [11] 等方法也在探索提升大语言模型输出的可控性，但直接利用大语言模型（LLM）生成高密度的动作网格极易导致逻辑坍塌，产生大量索引非法或格式缺失的无效输出。'
REST['其次是工艺约束在离散空间中的强耦合性'] = '其次是工艺约束在离散空间中的强耦合性。 横机针织不仅要求视觉上的纹理表达，更需严格遵循面向物理动作语义的离散结构约束。例如，线圈必须满足下方支撑（Support Constraint），移针动作必须符合床间位移上限 [12]。现有的基于扩散模型（如 Knit-FLUX [13]）的方法，大多将针织图案视为纯粹的视觉对象，缺少对底层动作间支撑关系与组合合法性的显式建模。'
REST['最后是缺乏将语义规划、约束编译与结构修复统一'] = '最后是缺乏将语义规划、约束编译与结构修复统一到同一生成链路中的方法。 现有的约束感知研究（如 KnitDiff [14]）多采用后置校验或局部优化。相比之下，虽然 Neural Inverse Knitting [15] 实现了从图像到指令的逆向映射，但仍无法在生成阶段实时感知并修复结构冲突。这导致生成结果往往具备视觉上的“欺骗性”，而在实际织造中会触发断纱、脱圈等严重工艺故障。因此，如何构建一种能够协同解析设计语义并在同一链路内完成约束编译与结构修复的生成框架，是当前智能针织制造领域亟待解决的瓶颈问题。'
REST['色码图生成虽是横机工业的主流需求'] = '色码图生成虽是横机针织工业的主流需求，但现有生成式方法多停留在视觉纹理图像 [5, 6, 13] 或线性机器指令序列 [15] 层面，缺乏以针迹级动作网格（stitch-level action grid）为直接生成目标的统一框架。针对自然语言设计语义难以直接映射到二维针迹动作结构的问题，本文创新性地将横机针织动作图生成建模为一个面向离散制造约束的语义到动作编译问题，提出以层次化语义约束编译为核心、以可编辑生成为目标的框架。本文的核心命题是：将规则库覆盖域内的自然语言设计语义映射为带父子区域关系的层次化结构计划与稀疏事件表示，并通过事件级约束编译而非像素级后处理生成满足离散工艺规则的动作网格。本文的主要贡献如下：'
REST['（1）提出层次化制造中间表示'] = '（1）提出层次化制造中间表示（Hierarchical Manufacturing IR）PatternPlan。 PatternPlan 不是简单的字段格式，而是一种连接规则库覆盖域内的设计语义与离散制造动作的领域特定中间表示，显式携带区域拓扑、几何作用域、纹理效果、工艺参数和父子层级关系，将覆盖域内的自然语言描述转化为可校验、可编辑和可编译的结构化计划。'
REST['（2）提出事件级动作约束编译与保守自修复'] = '（2）提出事件级动作约束编译与保守自修复方法。 本文将视觉目标生成、稀疏事件规划和动作网格构建分阶段处理，在事件层面维护成组结构完整性和区域边界归属，并结合动作索引、线圈支撑、移针关系和堆叠上限等约束，实现对二维动作图的生成过程控制。针对局部冲突，设计保守自修复机制，在优先保持区域轮廓和底布稳定性的同时删除或降级高风险动作。'
REST['（3）提出层次保持的结构可编辑生成机制'] = '（3）提出层次保持的结构可编辑生成机制。 基于 PatternPlan 的父子区域关系和事件的区域归属，本文支持对纹理、边框、背景和主体形状等语义维度进行单字段编辑，并通过层级作用域裁剪和非目标区域保持机制将编辑影响限制在目标区域内。在实验层面，本文进一步构建了覆盖语义解析、动作合法性、区域结构控制和局部可编辑性的评估协议，通过基线对比、模块消融、压力测试和可编辑生成实验分析各组件的作用及当前方法的适用边界。此外，上述可编辑生成机制已被封装为桌面原型系统（见补充材料 Section L），作为该机制的工程实现佐证。'
REST['此外，本文构建基于条件流匹配的结构感知视觉预览模块'] = '此外，本文构建了基于条件流匹配的结构感知视觉预览模块作为辅助验证接口：该模块融合中心动作、邻域动作和工艺属性先验，将离散动作图转换为针织外观预览，用于辅助检查区域边界和纹理连续性。该模块面向设计阶段的可视化反馈，属于框架的辅助组成部分，不构成本文的核心方法主张。'
REST['最后，本文系统已与宁波慈星股份有限公司合作完成工厂验证'] = '最后，本文系统已与宁波慈星股份有限公司合作完成工厂验证（4.5 节）：动作色码图与结构感知视觉预览图交付工厂后，经工厂打版流程转换在真实横机上织出成品样片，实物的区域几何与纹理结构均与设计一致，成品实物已在图 6 中展示，从数字生成到物理织造的链路在受控 5 例上初步验证了思路的可行性。'

# ---------- 2) 恢复第二章（相关工作） ----------
REST['自然语言驱动的生成技术已在图像合成'] = '近年来，自然语言驱动的生成技术在图像合成与指令驱动编辑 [16]、参数化布局及 3D 模型生成领域取得了长足进展 [8, 17]，其中 LayoutGPT [18] 验证了大语言模型以样式表语言直接生成空间布局的可行性。大语言模型（LLM）已展现出将设计意图转化为结构化脚本的能力：LLM4CAD [8] 利用多模态大语言模型生成三维 CAD 模型，Text2CAD [19] 则支持从不同细化程度的文本提示生成顺序化 CAD 建模序列，二者分别验证了多模态条件与纯文本条件下参数化建模的可行性。此外，近期研究进一步探索了将大语言模型引入从 CAD 到制造的设计流程，以增强工程设计的生成能力 [17]；Design2Code [20] 则从视觉设计到前端代码的自动转换角度，为多模态设计到代码生成提供了对照。然而，上述方法主要关注视觉内容或几何模型生成，缺乏针对针织制造过程中的工艺语义建模，无法生成可直接用于横机编织的动作结构。 与通用视觉对象不同，针织组织要求生成结果在离散网格上严格对齐物理动作语义，这使得现有的视觉驱动方法难以直接迁移至针织制造场景。'
REST['针织数字化设计的现有研究可分为三类'] = '针对针织领域的数字化设计，现有研究可分为以下三类：（1）视觉纹理生成：ColorwAI [5] 和 FabricDiffusion [6] 利用生成对抗网络（GAN）或扩散模型 [21, 22] 实现了高保真织物纹理的迁移与配色；条件扩散控制 [23] 与基于 Transformer 的扩散架构 [24] 进一步增强了此类生成的可控性与可扩展性；Knit-FLUX [13] 通过低秩适应（LoRA）提升了织物写实图像质量，但其输出仅限于 RGB 像素，缺乏底层动作语义。（2）指令逆向恢复与合成：Neural Inverse Knitting [15] 提出了从样片图像逆向推导机器指令的范式；deepKnit [25]、三维网格自动机器编织工具 AutoKnit [26] 和 Knit Sketching [27] 探索了从 3D 网格、剪裁缝纫样板或文本到指令序列的映射，但此类方法侧重于线性指令流，难以处理二维动作网格中的复杂拓扑关系。（3）新型表示与编译器：研究者提出了针织骨架（Knitting Skeletons）[28]、过程导向拓扑表示（TopoKnit）[29]、可视化横机编程工具 [4]、参数化针织设计工具 KNITIT [30]、面向三维机器编织的编译器 [31] 及其形式语义与调度框架 [32]、自动花型设计工具 skCAD [33] 与程序合成工具 KnitGIST [34] 等新型工具，它们通过高层原语简化了编织过程，但在处理自然语言驱动的开放式语义时灵活性不足。总体而言，现有方法主要面向视觉纹理生成、逆向指令恢复或约束优化，尚未实现自然语言设计意图到二维动作结构的统一生成；本文提出的 PatternPlan 旨在建立从语义到二维动作网格的直接映射，兼顾设计的自由度与制造的合规性。从表示与约束注入时机看，既有针织管线可分为线性指令流（Neural Inverse Knitting [15]、knitout [48]、三维机器编织编译器 [31, 32]）与程序合成式纹理生成（KnitGIST [34]）两类：前者以一维指令序列为对象、约束多在编译后期或后验阶段处理，后者面向视觉纹理程序；本文的差异在于以二维针迹动作网格为直接生成目标、在事件规划阶段显式注入区域归属与成组配对语义，并字段级支持区域编辑。'
REST['约束感知生成（Constraint-aware Generation）正成为制造领域研究热点'] = '受物理约束驱动的生成（Constraint-aware Generation）正成为制造领域的研究热点 [35]。传统的针织 CAD 系统（如 Stoll M1 Plus、SDS-ONE APEX [1, 2]）虽支持精细的针法编辑，但本质上是“绘图+编译”工具，缺乏工艺合规性的自动检测与实时修复能力。学术界近期尝试将工艺规则引入扩散过程，其中 KnitDiff [14] 是与本文最接近的工作：其同样面向针织图案的约束感知生成，但约束以后置校验与局部优化方式介入、生成目标非二维针迹动作网格、且未报告物理织造验证；本文则将约束前置于事件级编译阶段、以二维动作网格为直接生成目标并完成工厂实织验证。针织调度亦有过强化学习优化 [36]。此外，一些研究通过自动化三维机器编织的线圈建模来追踪线圈依赖关系 [26]。尽管如此，现有工作多聚焦于后置校验或局部优化，难以在生成阶段系统性地协同处理线圈支撑、移针偏移及张力平衡等强耦合约束。 本文通过构建知识引导的动作编译器，将约束检查前置于生成链路，实现了生成阶段的约束检查与保守修复闭环。'
REST['与本文对比的强约束生成范式有两条线索'] = '与本文第 4 章对比的强约束生成范式直接相关的有两条线索。其一是受约束解码（constrained decoding）：PICARD [11] 在自回归解码中增量检查形式语法约束，Grammar Prompting [10] 以领域特定语言的语法引导大语言模型生成合法程序，基于自动机的约束解码 [37] 将该思路推广到正则与上下文无关约束；这类方法保证生成序列在符号层的形式合法性，但不涉及生成内容的结构语义。其二是约束求解驱动的结构化合成：约束编程 [38] 提供了在离散变量域上声明并求解约束满足问题的通用框架，以 OR-Tools CP-SAT [39] 为代表的求解器已在调度与组合优化任务中广泛验证；在针织领域，KnitGIST [34] 以程序合成生成机器针织纹理，机器编织编译器的形式语义与调度框架 [32] 亦将约束求解纳入编译链路。总体而言，受约束解码与约束求解能够在符号层保证局部约束的可满足性，但区域归属、成组配对等结构语义无法从约束本身自动推出，需要由生成过程显式携带。 本文据此将 H1–H8 硬约束编码为 CP-SAT 约束满足模型，构造全局约束投影基线（基线定义见补充材料 Section M），并在 4.3.2 节定量检验“以约束求解替代事件级编译”的边界。'

for pre, new in REST.items():
    rewrite(pre, new)
print('restored:', len(REST))

# ---------- 3) 修 8a 遗留的悬空 4.1.x 引用（w:t 级） ----------
FIX = [('定义见 4.1.4）', '定义见补充材料 Section M）', 2),
       ('口径限制见 4.1.2 节）', '口径限制见补充材料 Section M）', 1),
       ('三类困难的弱基线（见 4.1.4 节）', '三类困难的弱基线（见补充材料 Section M）', 1),
       ('结构级指标（定义见 4.1.2 节）', '结构级指标（定义见补充材料 Section M）', 1),
       ('本身稀疏（见 4.1.2 节）', '本身稀疏（见补充材料 Section M）', 1),
       ('见 4.1.4 与 4.3.2 节）', '见补充材料 Section M 与 4.3.2 节）', 1)]
for old, new, c in FIX:
    n = 0
    for t in m.element.body.findall('.//' + qn('w:t')):
        if t.text and old in t.text:
            n += t.text.count(old); t.text = t.text.replace(old, new)
    assert n == c, (old, n)

# ---------- 校验 ----------
txt = '\n'.join(p.text for p in m.paragraphs)
CN = len(re.findall(r'[\u4e00-\u9fff]', txt))
assert not re.search(r'4\.1\.\d', txt), '仍有悬空 4.1.x 引用'
assert '3.6 节' not in txt, '仍有悬空 3.6 节'
cites = sorted(set(int(x) for t in re.findall(r'\[(\d+(?:,\s*\d+)*)\]', txt) for x in re.findall(r'\d+', t)))
assert cites == list(range(1, 49)), cites[:4]
figs = [int(re.match(r'^Fig\. (\d+)\.', p.text).group(1)) for p in m.paragraphs if re.match(r'^Fig\. \d+\.', p.text)]
assert figs == [1, 2, 3, 4, 5, 6], figs
m.save(MAIN)
print('OK round8c | main para CN=%d | figs=%s' % (CN, figs))
